def R(code, name, short, pop, pcrel, dev, unrest, auto, reg, tr, sec, infra, edu, health, env, mix, desc, E, Ecal=None):
    return dict(code=code, name=name, short=short, pop=pop, pcrel=pcrel, dev=dev, unrest=unrest, auto=auto, reg=reg, tr=tr,
                sec={"ind": sec[0], "agr": sec[1], "srv": sec[2], "res": sec[3]}, infra=infra, edu=edu, health=health, env=env, mix=mix, desc=desc, E=E, Ecal=Ecal)


# Список «Единство ради Венгрии» (2022) делим между партиями пропорционально их местам во фракциях:
# ДК 15, MSZP 10, Диалог 6 + LMP 5 (= 11), Моментум 10, Йоббик 10 (+ независимый Хадхази — в «прочих»)
def E22(fid, opp, mh, mkkp, minor):
    return [fid, mh, opp * 15 / 57, opp * 10 / 57, opp * 11 / 57, opp * 10 / 57, mkkp + opp * 1 / 57, opp * 10 / 57, minor, 0.0]


def Ecal(row, tisza):
    """для калибровки: доли 2022 года + региональный профиль «Тисы» по выборам в Европарламент 2024"""
    r = list(row); r[9] = tisza
    return r


